// LOKYX transaction encoding and signing for the Snap. The rules are the node's (src/tx.rs);
// test/snap.test.tsx checks the output against testdata/vectors.json generated by the node.

import { secp256k1 } from '@noble/curves/secp256k1.js';
import { keccak_256 } from '@noble/hashes/sha3.js';
import { bytesToHex, concatBytes, utf8ToBytes } from '@noble/hashes/utils.js';
import { bech32m } from '@scure/base';

export const COIN_TYPE = 7701;
export const MIN_FEE_PER_BYTE = 1_000_000_000_000n;
export const TX_VERSION = 2;
export const MAX_MEMO_BYTES = 64;
/** Size of a signed transfer with no memo  (see src/tx.rs). */
export const SIGNED_TRANSFER_BYTES = 168;
/** Signature: an enum tag byte (0 = secp256k1 recoverable), 64 bytes r||s, a recovery id. */
const SIG_BYTES = 66;
const COIN = 10n ** 18n;

export const NETWORKS: Record<string, string> = { '77701': 'Devnet', '77703': 'Testnet' };

export function addressFromPrivateKey(sk: Uint8Array): string {
  const pub = secp256k1.getPublicKey(sk, false);
  const payload = new Uint8Array(21);
  payload.set(keccak_256(pub.slice(1)).slice(12), 1);
  return bech32m.encode('lyx', bech32m.toWords(payload));
}

export function addressToBytes(addr: string): Uint8Array {
  const s = addr.trim();
  if (s !== s.toLowerCase() && s !== s.toUpperCase()) throw new Error('Mixed-case address');
  const { prefix, words } = bech32m.decode(s.toLowerCase() as `${string}1${string}`);
  if (prefix !== 'lyx') throw new Error('Not a LOKYX address');
  const bytes = bech32m.fromWords(words);
  if (bytes.length !== 21 || bytes[0] !== 0) throw new Error('Invalid LOKYX address');
  return bytes.slice(1);
}

export interface Transfer {
  chainId: bigint;
  nonce: bigint;
  to: string;
  value: bigint;
  fee: bigint;
  /** Last block it may be included in; 0 means never expires. */
  expires?: bigint;
  memo?: Uint8Array;
}

function uintLE(v: bigint, bytes: number): Uint8Array {
  if (v < 0n || v >= 1n << BigInt(bytes * 8)) throw new Error('Number out of range');
  const out = new Uint8Array(bytes);
  for (let i = 0; i < bytes; i++) {
    out[i] = Number(v & 0xffn);
    v >>= 8n;
  }
  return out;
}

/** Borsh bytes of the transaction (src/tx.rs, format v2) for a plain transfer from the signing key's own address. */
export function encodeTx(t: Transfer, from: string): Uint8Array {
  const memo = t.memo ?? new Uint8Array();
  if (memo.length > MAX_MEMO_BYTES) throw new Error(`A memo is at most ${MAX_MEMO_BYTES} bytes`);
  return concatBytes(
    Uint8Array.of(TX_VERSION),
    uintLE(t.chainId, 8),
    addressToBytes(from),
    uintLE(t.nonce, 8),
    uintLE(t.expires ?? 0n, 8),
    uintLE(t.fee, 16),
    uintLE(BigInt(memo.length), 4),
    memo,
    Uint8Array.of(0), // Op::Transfer
    addressToBytes(t.to),
    uintLE(t.value, 16),
  );
}

/** The least fee the node accepts for this transfer: its signed size times the per-byte price. */
export function minTransferFee(t: Omit<Transfer, 'fee'>, from: string): bigint {
  return BigInt(encodeTx({ ...t, fee: 0n }, from).length + SIG_BYTES) * MIN_FEE_PER_BYTE;
}

export function signTransfer(t: Transfer, sk: Uint8Array): { tx: string; hash: string; from: string } {
  const from = addressFromPrivateKey(sk);
  const body = encodeTx(t, from);
  const digest = keccak_256(concatBytes(utf8ToBytes('LOKYX/tx/v2'), body));
  const rec = secp256k1.sign(digest, sk, { prehash: false, format: 'recovered' });
  const bytes = concatBytes(body, Uint8Array.of(0), rec.slice(1, 65), rec.slice(0, 1));
  return { tx: bytesToHex(bytes), hash: bytesToHex(keccak_256(bytes)), from };
}

export function formatLyx(v: bigint): string {
  const whole = v / COIN;
  const frac = (v % COIN).toString().padStart(18, '0').replace(/0+$/, '');
  return frac ? `${whole}.${frac}` : `${whole}`;
}
